// Still-photo capture -> file URI + 224x224 RGB tensor. Uses only APIs verified in
// node_modules/react-native-vision-camera@5.2.3 and react-native-nitro-image@0.15.2.
import React, { useCallback, useEffect, useRef, useState } from 'react'
import { Image as RNImage, Linking, Pressable, StyleSheet, Text, View } from 'react-native'
import { useIsFocused } from 'expo-router'
import {
  Camera,
  CommonResolutions,
  useCameraDevice,
  useCameraPermission,
  usePhotoOutput,
  type FlashMode,
} from 'react-native-vision-camera'

const INPUT = 224

export function CaptureScreen() {
  const { hasPermission, canRequestPermission, requestPermission } = useCameraPermission()
  const device = useCameraDevice('back') // undefined until the device factory loads
  const isFocused = useIsFocused()
  const [photoUri, setPhotoUri] = useState<string>()
  const busy = useRef(false)

  // Options must be referentially stable: use the CommonResolutions constant, never an inline {width,height}.
  const photoOutput = usePhotoOutput({
    targetResolution: CommonResolutions.HD_4_3, // small: toImage() decodes a full Bitmap
    containerFormat: 'jpeg',                    // 'heic' throws on Android
    quality: 0.85,                              // 0..1 here (nitro-image uses 0..100)
    qualityPrioritization: 'balanced',          // 'speed' needs device.supportsSpeedQualityPrioritization
  })

  useEffect(() => {
    if (!hasPermission && canRequestPermission) requestPermission()
  }, [hasPermission, canRequestPermission, requestPermission])

  const onShutter = useCallback(async () => {
    if (busy.current) return
    busy.current = true
    try {
      const flashMode: FlashMode = 'off' // 'on' throws if !device.hasFlash
      // BOTH args are required; pass {} for callbacks.
      const photo = await photoOutput.capturePhoto({ flashMode, enableShutterSound: false }, {})
      try {
        // 1) File for <Image> / upload. Plain path, no scheme -> add file://
        const path = await photo.saveToTemporaryFileAsync()
        setPhotoUri(`file://${path}`)

        // 2) Upright in-memory image (rotation + mirroring physically applied)
        const full = await photo.toImageAsync()
        const side = Math.min(full.width, full.height)
        const x0 = Math.floor((full.width - side) / 2)
        const y0 = Math.floor((full.height - side) / 2)
        const square = await full.cropAsync(x0, y0, x0 + side, y0 + side) // (startX,startY,endX,endY)
        const small = await square.resizeAsync(INPUT, INPUT)               // resize stretches -> crop first
        const raw = await small.toRawPixelDataAsync()                      // Android: 'RGBA', 4 bytes/px

        const src = new Uint8Array(raw.buffer)
        const rgb = new Uint8Array(INPUT * INPUT * 3) // use Float32Array + normalisation for a float model
        const fmt = raw.pixelFormat
        const [r, g, b] =
          fmt === 'RGBA' || fmt === 'RGBX' ? [0, 1, 2]
          : fmt === 'BGRA' || fmt === 'BGRX' ? [2, 1, 0]
          : fmt === 'ARGB' || fmt === 'XRGB' ? [1, 2, 3]
          : [3, 2, 1] // ABGR / XBGR
        for (let i = 0, o = 0; i < INPUT * INPUT; i++, o += 3) {
          const p = i * 4
          rgb[o] = src[p + r]; rgb[o + 1] = src[p + g]; rgb[o + 2] = src[p + b]
        }
        // -> hand `rgb` to the tflite model here

        full.dispose(); square.dispose(); small.dispose()
      } finally {
        photo.dispose() // closes the underlying CameraX ImageProxy
      }
    } catch (e) {
      console.error('capture failed', e)
    } finally {
      busy.current = false
    }
  }, [photoOutput])

  if (!hasPermission) {
    return (
      <View style={styles.center}>
        <Text>Camera permission is required.</Text>
        <Pressable onPress={() => (canRequestPermission ? requestPermission() : Linking.openSettings())}>
          <Text>Grant</Text>
        </Pressable>
      </View>
    )
  }
  if (device == null) return <View style={styles.center}><Text>No camera</Text></View>

  return (
    <View style={StyleSheet.absoluteFill}>
      <Camera
        style={StyleSheet.absoluteFill}
        device={device}               // or simply device="back"
        isActive={isFocused}          // app-background pause is handled natively on Android
        outputs={[photoOutput]}       // preview output is added internally by <Camera>
        resizeMode="cover"
        onError={(e) => console.warn('camera error', e)}
      />
      {photoUri != null && <RNImage source={{ uri: photoUri }} style={styles.thumb} />}
      <Pressable style={styles.shutter} onPress={onShutter} />
    </View>
  )
}

const styles = StyleSheet.create({
  center: { flex: 1, alignItems: 'center', justifyContent: 'center' },
  thumb: { position: 'absolute', left: 16, bottom: 32, width: 64, height: 64, borderRadius: 8 },
  shutter: { position: 'absolute', alignSelf: 'center', bottom: 32, width: 72, height: 72, borderRadius: 36, backgroundColor: '#fff' },
})

// src/ai/classifier.ts  -- plain JS, no worklet, no React required.
// Uses ONLY APIs verified in node_modules/react-native-fast-tflite@3.0.1.
import { loadTensorflowModel, type TfliteModel, type Tensor } from 'react-native-fast-tflite'

type DataType = Tensor['dataType'] // TensorDataType is not exported from the package index

interface LoadedClassifier {
  model: TfliteModel
  input: Tensor   // cached: `model.inputs` is a native getter that rebuilds the array each access
  output: Tensor
  width: number
  height: number
}

// Module-level singleton: lives for the app's lifetime, outside React.
let loading: Promise<LoadedClassifier> | null = null

export function getClassifier(): Promise<LoadedClassifier> {
  if (loading == null) {
    loading = (async () => {
      // delegates is REQUIRED; [] === default CPU. There is no 'default'/'cpu' string in v3.
      const model = await loadTensorflowModel(require('../../assets/models/mobilenet.tflite'), [])
      const input = model.inputs[0]
      const output = model.outputs[0]
      if (input == null || output == null) throw new Error('Model has no input/output tensor')
      // Expect NHWC [1, H, W, 3]
      const [, height, width, channels] = input.shape
      if (input.shape.length !== 4 || channels !== 3 || height == null || width == null) {
        throw new Error(`Unexpected input shape ${JSON.stringify(input.shape)}`)
      }
      if (input.dataType !== 'uint8' && input.dataType !== 'float32') {
        throw new Error(`Unsupported input dataType ${input.dataType}`)
      }
      return { model, input, output, width, height }
    })()
    loading.catch(() => { loading = null }) // allow retry after a failed load
  }
  return loading
}

/** rgb: tightly packed RGB bytes, length === width*height*3, produced elsewhere (nitro-image). */
function buildInput(rgb: Uint8Array, dataType: DataType): ArrayBuffer {
  if (dataType === 'uint8') {
    // Fresh, exactly-sized, zero-offset buffer. Native side uses the WHOLE ArrayBuffer.
    const copy = new Uint8Array(rgb.length)
    copy.set(rgb)
    return copy.buffer
  }
  // float32 MobileNet convention: [-1, 1]. (Some float models want [0,1] - model specific.)
  const f = new Float32Array(rgb.length)
  for (let i = 0; i < rgb.length; i++) f[i] = (rgb[i]! - 127.5) / 127.5
  return f.buffer
}

function readScores(buf: ArrayBuffer, dataType: DataType): number[] {
  // COPY immediately: the native output ArrayBuffer is cached per tensor and overwritten by the next run.
  if (dataType === 'uint8') return Array.from(new Uint8Array(buf), (v) => v / 255) // no scale/zero_point exposed
  if (dataType === 'int8') return Array.from(new Int8Array(buf), (v) => (v + 128) / 255)
  if (dataType === 'float32') return Array.from(new Float32Array(buf))
  throw new Error(`Unsupported output dataType ${dataType}`)
}

let busy: Promise<unknown> = Promise.resolve() // serialize: interpreter has no lock

export function classify(rgb: Uint8Array, topK = 5): Promise<{ index: number; score: number }[]> {
  const job = busy.then(async () => {
    const c = await getClassifier()
    const expected = c.width * c.height * 3
    if (rgb.length !== expected) throw new Error(`Expected ${expected} RGB bytes, got ${rgb.length}`)
    const outputs = await c.model.run([buildInput(rgb, c.input.dataType)]) // inference on Nitro thread pool
    const first = outputs[0]
    if (first == null) throw new Error('Model returned no outputs')
    const scores = readScores(first, c.output.dataType)
    return scores
      .map((score, index) => ({ index, score }))
      .sort((a, b) => b.score - a.score)
      .slice(0, topK)
  })
  busy = job.catch(() => undefined)
  return job
}

