import { Image as RNImage } from 'react-native'
import type { Image } from 'react-native-nitro-image'
import type { CameraPhotoOutput } from 'react-native-vision-camera'
import type { TfliteModel } from 'react-native-fast-tflite'

// const photoOutput = usePhotoOutput({ targetResolution: CommonResolutions.FHD_4_3, containerFormat: 'jpeg', quality: 0.85 })
// <Camera device={device} isActive outputs={[photoOutput]} />

const SIZE = 224

export async function captureAndClassify(photoOutput: CameraPhotoOutput, model: TfliteModel) {
  const photo = await photoOutput.capturePhoto({ flashMode: 'off' }, {}) // both args required
  const images: Image[] = []
  try {
    // (4) original JPEG (+EXIF) for display/upload. Bare path, no file:// prefix.
    const photoPath = await photo.saveToTemporaryFileAsync()
    const photoUri = `file://${photoPath}`

    // (1) Photo -> nitro Image, orientation + mirroring already applied to the pixels
    const full = await photo.toImageAsync()
    images.push(full)

    // (2) center-crop to square. crop() takes START/END coords, not x/y/w/h.
    const side = Math.min(full.width, full.height)
    const x0 = Math.floor((full.width - side) / 2)
    const y0 = Math.floor((full.height - side) / 2)
    let square = full
    if (full.width !== full.height) {
      square = await full.cropAsync(x0, y0, x0 + side, y0 + side)
      images.push(square)
    }
    const small = await square.resizeAsync(SIZE, SIZE)
    images.push(small)

    // (3) raw pixels: 4 bytes/pixel, format must be READ, not assumed ('RGBA' on Android, usually 'BGRA' on iOS)
    const raw = small.toRawPixelData() // sync is fine for 224x224 (~200 KB); keep allowGpu unset
    const src = new Uint8Array(raw.buffer)
    const w = raw.width, h = raw.height
    const stride = src.byteLength / h // == w * 4 when tightly packed (expected)
    let rOff: number, gOff: number, bOff: number
    switch (raw.pixelFormat) {
      case 'RGBA': case 'RGBX': rOff = 0; gOff = 1; bOff = 2; break
      case 'BGRA': case 'BGRX': rOff = 2; gOff = 1; bOff = 0; break
      case 'ARGB': case 'XRGB': rOff = 1; gOff = 2; bOff = 3; break
      case 'ABGR': case 'XBGR': rOff = 3; gOff = 2; bOff = 1; break
      default: throw new Error(`Unsupported pixelFormat ${raw.pixelFormat}`)
    }

    const inputInfo = model.inputs[0] // { name, dataType, shape } e.g. [1,224,224,3]
    const isFloat = inputInfo?.dataType === 'float32'
    const rgb = isFloat ? new Float32Array(w * h * 3) : new Uint8Array(w * h * 3)
    let o = 0
    for (let y = 0; y < h; y++) {
      let i = y * stride
      for (let x = 0; x < w; x++, i += 4) {
        const r = src[i + rOff]!, g = src[i + gOff]!, b = src[i + bOff]!
        if (isFloat) { // MobileNet float convention: [-1, 1]; change if your model wants [0,1]
          rgb[o++] = (r - 127.5) / 127.5; rgb[o++] = (g - 127.5) / 127.5; rgb[o++] = (b - 127.5) / 127.5
        } else { rgb[o++] = r; rgb[o++] = g; rgb[o++] = b }
      }
    }

    // fast-tflite 3.0.1 takes ArrayBuffer[] and returns ArrayBuffer[]
    const [out] = await model.run([rgb.buffer as ArrayBuffer])
    const scores = model.outputs[0]?.dataType === 'float32' ? new Float32Array(out!) : new Uint8Array(out!)

    return { photoUri, photoPath, scores }
  } finally {
    // (6) dispose AFTER pixels are read; raw.buffer is an independent copy and stays valid
    for (const img of images) img.dispose()
    photo.dispose()
  }
}

// (5) display: <RNImage source={{ uri: photoUri }} style={{ width: 200, height: 200 }} />
