// src/app/camera.tsx. The root <Stack> already sets headerShown: false, so no babel.config.js is required.
import { useCallback, useState } from 'react';
import { StyleSheet, useWindowDimensions } from 'react-native';
import { useIsFocused, Stack } from 'expo-router';
import Animated, {
  Easing,
  interpolate,
  useAnimatedStyle,
  useSharedValue,
  withDelay,
  withSpring,
  withTiming,
  SnappySpringConfig,
} from 'react-native-reanimated';
import { scheduleOnRN } from 'react-native-worklets';

const SLOT = 64;

export default function CameraRoute() {
  const isFocused = useIsFocused();              // from 'expo-router', NOT @react-navigation/native
  const { width: W, height: H } = useWindowDimensions();
  const [photoUri, setPhotoUri] = useState<string | null>(null);
  const [settled, setSettled] = useState(false);

  const progress = useSharedValue(0);            // 0 = full-screen photo, 1 = docked in the 64x64 slot
  const sheetY = useSharedValue(H);              // sheet starts off-screen at the bottom

  const SHEET_H = H * 0.6;
  const slotX = 16;                              // slot position in screen coordinates
  const slotY = H - SHEET_H + 16;

  const onSettled = useCallback(() => setSettled(true), []);

  const play = useCallback(() => {
    // Reduce motion: the default is ReduceMotion.System, so the values snap to the end
    // and the callback still fires with finished === true. No manual branching needed.
    sheetY.value = withSpring(H - SHEET_H, SnappySpringConfig);
    progress.value = withDelay(
      80,
      withTiming(1, { duration: 420, easing: Easing.out(Easing.cubic) }, (finished) => {
        'worklet';
        if (finished) scheduleOnRN(onSettled);   // args go inline: scheduleOnRN(fn, a, b)
      })
    );
  }, [H, SHEET_H, onSettled, progress, sheetY]);

  const photoStyle = useAnimatedStyle(() => {
    const s = interpolate(progress.value, [0, 1], [1, SLOT / W]);
    // The view is W x H with its origin at top-left. Scaling happens about the centre, so compensate.
    const tx = interpolate(progress.value, [0, 1], [0, slotX + SLOT / 2 - W / 2]);
    const ty = interpolate(progress.value, [0, 1], [0, slotY + SLOT / 2 - H / 2]);
    return {
      transform: [{ translateX: tx }, { translateY: ty }, { scale: s }],
      borderRadius: interpolate(progress.value, [0, 1], [0, 12 / s]),
    };
  });

  const sheetStyle = useAnimatedStyle(() => ({ transform: [{ translateY: sheetY.value }] }));

  return (
    <>
      <Stack.Screen options={{ headerShown: false, animation: 'fade' }} />
      {/* <Camera isActive={isFocused && photoUri == null} device="back" outputs={[photoOutput]} ... /> */}
      <Animated.View style={[styles.sheet, { height: SHEET_H }, sheetStyle]} />
      {photoUri != null && (
        <Animated.Image
          source={{ uri: photoUri }}
          style={[{ position: 'absolute', left: 0, top: 0, width: W, height: H }, photoStyle]}
          resizeMode="cover"
        />
      )}
    </>
  );
}

const styles = StyleSheet.create({
  sheet: { position: 'absolute', left: 0, right: 0, top: 0, backgroundColor: '#0D0E0C' },
});

