import React, { useCallback, useEffect, useRef, useState } from 'react'
import { Image as RNImage, Linking, Pressable, StyleSheet, Text, View } from 'react-native'
import { useIsFocused } from 'expo-router'
import { Camera, CommonResolutions, useCameraPermission, usePhotoOutput, type CameraPhotoOutput } from 'react-native-vision-camera'
import type { Image as NitroImg, RawPixelData } from 'react-native-nitro-image'
import { loadTensorflowModel, type Tensor, type TfliteModel } from 'react-native-fast-tflite'

// ---- model assets: NEITHER FILE EXISTS YET under C:\dk\mobile\assets (glob for *.tflite returned nothing) ----
const MODEL_SOURCE: number = require('../../assets/models/mobilenet_224.tflite')
const LABELS: string[] = require('../../assets/models/labels.json')
// Only used when inputs[0].dataType === 'float32'. NOT discoverable via the API; record it with the model.
const FLOAT_MEAN = 127.5, FLOAT_STD = 127.5 // classic MobileNet [-1,1]; some models want mean 0 / std 255

type DType = Tensor['dataType'] // TensorDataType is not re-exported from the package index (src\index.ts)
interface Classifier { model: TfliteModel; inType: DType; outType: DType; size: number; outLen: number }

let loading: Promise<Classifier> | null = null
export function getClassifier(): Promise<Classifier> {
  if (loading == null) {
    loading = (async () => {
      const model = await loadTensorflowModel(MODEL_SOURCE, []) // [] = CPU. There is no 'default' delegate string in v3.
      const input = model.inputs[0], output = model.outputs[0] // native getters rebuild arrays on each access: read once
      if (input == null || output == null) throw new Error('model has no input/output tensor')
      const [n, h, w, ch] = input.shape
      if (input.shape.length !== 4 || n !== 1 || h !== w || ch !== 3 || h == null) throw new Error('unexpected input shape ' + JSON.stringify(input.shape))
      if (input.dataType !== 'uint8' && input.dataType !== 'float32') throw new Error('unsupported input type ' + input.dataType)
      const outLen = output.shape.reduce((a, b) => a * b, 1)
      return { model, inType: input.dataType, outType: output.dataType, size: h, outLen }
    })()
    loading.catch(() => { loading = null })
  }
  return loading
}

/** nitro-image RawPixelData (4 or 3 bytes/px) -> tightly packed tensor bytes. Branch on pixelFormat, never assume. */
function toInputBuffer(raw: RawPixelData, size: number, inType: DType): ArrayBuffer {
  if (raw.width !== size || raw.height !== size) throw new Error(`expected ${size}x${size}, got ${raw.width}x${raw.height}`)
  const f = raw.pixelFormat
  const bpp = f === 'RGB' || f === 'BGR' ? 3 : 4
  let r: number, g: number, b: number
  if (f === 'RGBA' || f === 'RGBX' || f === 'RGB') { r = 0; g = 1; b = 2 }       // Android ARGB_8888 reports 'RGBA'
  else if (f === 'BGRA' || f === 'BGRX' || f === 'BGR') { r = 2; g = 1; b = 0 }  // typical iOS
  else if (f === 'ARGB' || f === 'XRGB') { r = 1; g = 2; b = 3 }
  else if (f === 'ABGR' || f === 'XBGR') { r = 3; g = 2; b = 1 }
  else throw new Error('unsupported pixelFormat ' + f)
  const src = new Uint8Array(raw.buffer)
  const px = size * size
  if (src.length < px * bpp) throw new Error('raw pixel buffer too small')
  // Fresh, exactly-sized, zero-offset typed array: native copies the WHOLE ArrayBuffer and ignores a size mismatch silently.
  if (inType === 'uint8') {
    const out = new Uint8Array(px * 3)                    // 150528 bytes for 224
    for (let i = 0, p = 0, o = 0; i < px; i++, p += bpp, o += 3) { out[o] = src[p + r]!; out[o + 1] = src[p + g]!; out[o + 2] = src[p + b]! }
    return out.buffer
  }
  const out = new Float32Array(px * 3)                    // 602112 bytes for 224
  for (let i = 0, p = 0, o = 0; i < px; i++, p += bpp, o += 3) {
    out[o] = (src[p + r]! - FLOAT_MEAN) / FLOAT_STD; out[o + 1] = (src[p + g]! - FLOAT_MEAN) / FLOAT_STD; out[o + 2] = (src[p + b]! - FLOAT_MEAN) / FLOAT_STD
  }
  return out.buffer
}

function readScores(buf: ArrayBuffer, t: DType): number[] {
  // COPY NOW: the native output ArrayBuffer is cached per tensor name and overwritten by the next run().
  if (t === 'uint8') return Array.from(new Uint8Array(buf), (v) => v / 255) // no scale/zero_point exposed; monotonic so ranking is exact
  if (t === 'int8') return Array.from(new Int8Array(buf), (v) => (v + 128) / 255)
  if (t === 'float32') return Array.from(new Float32Array(buf))
  throw new Error('unsupported output type ' + t)
}

export interface Prediction { index: number; label: string; score: number }
export interface ClassifiedPhoto { uri: string; path: string; predictions: Prediction[] }

let chain: Promise<unknown> = Promise.resolve() // the interpreter has no mutex and run() goes to a thread pool: serialize in JS

export function captureAndClassify(photoOutput: CameraPhotoOutput, topK = 3): Promise<ClassifiedPhoto> {
  const job = chain.then(async () => {
    const c = await getClassifier() // load BEFORE the shutter in real code; createModel is a sync native call on the JS thread
    let full: NitroImg | undefined, square: NitroImg | undefined, small: NitroImg | undefined
    try {
      const photo = await photoOutput.capturePhoto({ flashMode: 'off', enableShutterSound: false }, {}) // {} callbacks is mandatory
      try { full = await photo.toImageAsync() }   // upright Bitmap: rotation by imageInfo.rotationDegrees + mirroring already applied
      finally { photo.dispose() }                 // closes the CameraX ImageProxy; safe here because toImage() produced its own Bitmap
      // File for <Image> + later upload, written from the UPRIGHT bitmap so nothing depends on EXIF handling.
      // Plain path with NO scheme. nitro-image quality is 0..100 (PhotoOutputOptions.quality is 0..1).
      const path = await full.saveToTemporaryFileAsync('jpg', 85)
      // Center-crop to a square FIRST: resize() is Bitmap.scale(w,h,true) and stretches. crop takes (startX,startY,endX,endY).
      const side = Math.min(full.width, full.height)
      const x0 = Math.floor((full.width - side) / 2), y0 = Math.floor((full.height - side) / 2)
      square = await full.cropAsync(x0, y0, x0 + side, y0 + side)
      small = await square.resizeAsync(c.size, c.size)
      const raw = await small.toRawPixelDataAsync() // allowGpu omitted => CPU copy via copyPixelsToBuffer
      const input = toInputBuffer(raw, c.size, c.inType)
      const outputs = await c.model.run([input]) // ArrayBuffer[], not TypedArray[]
      const first = outputs[0]
      if (first == null) throw new Error('model returned no outputs')
      const scores = readScores(first, c.outType)
      const offset = scores.length === LABELS.length + 1 ? 1 : 0 // 1001-class ImageNet models have a leading 'background'
      const predictions = scores
        .map((score, index) => ({ index, score, label: LABELS[index - offset] ?? `#${index}` }))
        .sort((a, b) => b.score - a.score)
        .slice(0, topK)
      return { uri: `file://${path}`, path, predictions }
    } finally {
      // Dispose only AFTER pixels are read: Android Bitmap.createBitmap/scale may hand back the same Bitmap for a no-op
      // crop/resize (framework behaviour, not in these sources), and dispose() == bitmap.recycle().
      small?.dispose(); square?.dispose(); full?.dispose()
    }
  })
  chain = job.catch(() => undefined)
  return job
}

export function CaptureScreen() {
  const { hasPermission, canRequestPermission, requestPermission } = useCameraPermission()
  const isFocused = useIsFocused()
  const [ready, setReady] = useState(false)
  const [result, setResult] = useState<ClassifiedPhoto>()
  const busy = useRef(false)
  // Option values are useMemo deps compared by reference: use the module-level constant, never an inline {width,height}.
  const photoOutput = usePhotoOutput({ targetResolution: CommonResolutions.HD_4_3, containerFormat: 'jpeg', quality: 0.85, qualityPrioritization: 'balanced' })

  useEffect(() => { getClassifier().catch((e) => console.warn('model load failed', e)) }, []) // warm up off the shutter path
  useEffect(() => { if (!hasPermission && canRequestPermission) void requestPermission() }, [hasPermission, canRequestPermission, requestPermission])

  const onShutter = useCallback(async () => {
    if (busy.current || !ready) return
    busy.current = true
    try { setResult(await captureAndClassify(photoOutput)) }
    catch (e) { console.warn('capture/classify failed', e) } // e.g. 'Photo Output is not yet attached to the CameraSession!'
    finally { busy.current = false }
  }, [photoOutput, ready])

  if (!hasPermission) {
    return (
      <View style={styles.center}>
        <Pressable onPress={() => (canRequestPermission ? requestPermission() : Linking.openSettings())}><Text>Allow camera</Text></Pressable>
      </View>
    )
  }
  return (
    <View style={StyleSheet.absoluteFill}>
      <Camera
        style={StyleSheet.absoluteFill}
        device="back"               // CameraProps.device accepts the position string; no useCameraDevice needed
        isActive={isFocused}        // navigation focus is NOT known to the library; app background is handled natively
        outputs={[photoOutput]}     // <Camera> prepends its own preview output
        onStarted={() => setReady(true)}
        onError={(e) => console.warn('camera error', e)}
      />
      {result != null && <RNImage source={{ uri: result.uri }} style={styles.thumb} />}
      {result?.predictions.map((p) => <Text key={p.index}>{p.label} {(p.score * 100).toFixed(0)}%</Text>)}
      <Pressable style={styles.shutter} onPress={onShutter} />
    </View>
  )
}

const styles = StyleSheet.create({
  center: { flex: 1, alignItems: 'center', justifyContent: 'center' },
  thumb: { position: 'absolute', left: 16, bottom: 32, width: 64, height: 64, borderRadius: 8 },
  shutter: { position: 'absolute', alignSelf: 'center', bottom: 32, width: 72, height: 72, borderRadius: 36, backgroundColor: '#fff' },
})

